r IV\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.damage.useDamageSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/thunder_v.lua"]={["Path"]="scripts/actions/spells/black/thunder_v.lua",["SHA256"]="950ccd6557ac2a87143cabdd5f98ebbba7b037b6af04118c13ab5abc96ebbf76",["Text"]="-----------------------------------\n-- Spell: Thunder V\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.damage.useDamageSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/thunder_vi.lua"]={["Path"]="scripts/actions/spells/black/thunder_vi.lua",["SHA256"]="33666668809f8f3d51451ee861574a1b98e9bd12009d27b0f57d5bc377b0ff1f",["Text"]="-----------------------------------\n-- Spell: Thunder VI\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.damage.useDamageSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/tornado.lua"]={["Path"]="scripts/actions/spells/black/tornado.lua",["SHA256"]="daffd4aefbe769b9606262e8a52bd594221cb5bc2a23ba1e98314bce2090107e",["Text"]="-----------------------------------\n-- Spell: Tornado\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    target:addStatusEffect(xi.effect.NINJUTSU_ELE_DEBUFF, { power = 30, duration = 10, origin = caster, icon = 0, subPower = xi.mod.ICE_MEVA })\n\n    return xi.spells.damage.useDamageSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/tornado_ii.lua"]={["Path"]="scripts/actions/spells/black/tornado_ii.lua",["SHA256"]="ffd9ebc250795f28dfe916b7b371146037765e960041f27cf973d9d260793997",["Text"]="-----------------------------------\n-- Spell: Tornado II\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    target:addStatusEffect(xi.effect.NINJUTSU_ELE_DEBUFF, { power = 30, duration = 10, origin = caster, icon = 0, subPower = xi.mod.ICE_MEVA })\n\n    return xi.spells.damage.useDamageSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/tractor.lua"]={["Path"]="scripts/actions/spells/black/tractor.lua",["SHA256"]="9dcc8314a43de23d168d81e51f697653c17766db3ccdd4d233ffba8ff196740e",["Text"]="-----------------------------------\n-- Spell: Tractor\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    if\n        target:isMob() or                             -- Because Prishe in CoP mission.\n        target:isAlive() or                           -- Can't cast on alive targets.\n        target:hasRaiseTractorMenu() or               -- Raise and tractor menus both block the casting.\n        target:hasStatusEffect(xi.effect.BATTLEFIELD) -- Cannot be cast on BCNMs.\n    then\n        return xi.msg.basic.CANNOT_ON_THAT_TARG\n    end\n\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    if target:getObjType() == xi.objType.PC then\n        target:sendTractor(caster:getXPos(), caster:getYPos(), caster:getZPos(), target:getRotPos())\n        spell:setMsg(xi.msg.basic.MAGIC_CASTS_ON)\n        return 1\n    end\n\n    return 0\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/virus.lua"]={["Path"]="scripts/actions/spells/black/virus.lua",["SHA256"]="55a5d9ea44575ea3715088b19a0fbc79c324b15d6a09096343ccb4dfff5ccaa3",["Text"]="-----------------------------------\n-- Spell: Virus\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enfeebling.useEnfeeblingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/warp.lua"]={["Path"]="scripts/actions/spells/black/warp.lua",["SHA256"]="469296f4d6ef0225b673fc5e7e46f62108773efef7f67105911202e47d0b95a8",["Text"]="-----------------------------------\n-- Spell: Warp\n-- Transports the user to their Home Point\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enhancing.useTeleportSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/warp_ii.lua"]={["Path"]="scripts/actions/spells/black/warp_ii.lua",["SHA256"]="710f2a7f4096d214ece9bcd779dc5c614a11cc94f65b6ac2bbc4fb4312c2eeef",["Text"]="-----------------------------------\n-- Spell: Warp II\n-- Transports player to their home point. Can cast on allies.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    if target:hasStatusEffect(xi.effect.MOUNTED) then\n        return xi.msg.basic.MAGIC_CANNOT_BE_CAST\n    end\n\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enhancing.useTeleportSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/water.lua"]={["Path"]="scripts/actions/spells/black/water.lua",["SHA256"]="1ac2aae9071f41031f1efb6424b0f8fe45c9635d3672e002690a1afd188ac678",["Text"]="-----------------------------------\n-- Spell: Water\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.damage.useDamageSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/water_ii.lua"]={["Path"]="scripts/actions/spells/black/water_ii.lua",["SHA256"]="d71f9b73f7b1c02d23a20729bfcb1cee6e61dc52bb679aeb329a183d2b783808",["Text"]="-----------------------------------\n-- Spell: Water II\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.damage.useDamageSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/water_iii.lua"]={["Path"]="scripts/actions/spells/black/water_iii.lua",["SHA256"]="142deb43c59bd3c961b37b5f32465f437e84e439b5039d79c323d5811768ba5a",["Text"]="-----------------------------------\n-- Spell: Water III\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.damage.useDamageSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/water_iv.lua"]={["Path"]="scripts/actions/spells/black/water_iv.lua",["SHA256"]="653b560f0422d34e5bc92171cce1a19604256c4bad1fc5cf9b956cad3db20f02",["Text"]="-----------------------------------\n-- Spell: Water IV\n------------------------------